from pathlib import Path
import csv,json,math,statistics
R=Path(__file__).resolve().parent
def summarize():
 records=json.loads((R/'BATCH_LEDGER.json').read_text())if(R/'BATCH_LEDGER.json').exists()else[];groups=[];rng=[]
 for case in ['A2','B2','C3','D4','E3']:
  z=[x['QA']for x in records if x['QA']['case']==case];decl=[x for x in z if x.get('official_success')];errors=[x['terminal']['Top5_error_m']for x in decl if'terminal'in x];times=[x['search_physical_s']for x in decl if x.get('search_physical_s')is not None];groups.append(dict(case=case,completed=len(z),native_declared=len(decl),native_declaration_rate=len(decl)/len(z)if z else None,source_domain='EXCLUDED_DIAGNOSTIC_ONLY'if case=='B2'else'LEGAL',declared_Top5_errors_m=json.dumps(errors),mean_declared_error_m=statistics.mean(errors)if errors else None,min_declared_error_m=min(errors)if errors else None,max_declared_error_m=max(errors)if errors else None,mean_declared_search_physical_s=statistics.mean(times)if times else None,censored=sum('CENSORED'in x.get('qualification','')for x in z),technical=sum(not x.get('qualification','').startswith('PASS')for x in z)))
 for x in records:
  q=x['QA'];states=q.get('first_RNG_states',[]);seen=[(z['before']if z['before'].get('ui')else z['after']if z['after'].get('ui')else None)for z in states];rng.append(dict(role=x['role'],actual_available_uniform_seeds=[z.get('seed')if z else'UNKNOWN_NOT_INITIALIZED_AT_CAPTURE'for z in seen],capture_phase=['before'if z['before'].get('ui')else'after'if z['after'].get('ui')else'UNAVAILABLE'for z in states],actual_first_engine_states=[z['before'].get('engine')for z in states],cache_hashes=[z['sha256']for z in q.get('RNG_caches',[])],interpretation='Before.ui=False means seed field0 is a placeholder, not a captured seed. Equal Gaussian tables do not imply identical consumed order; offsets/thread ownership may differ. Different uniform seeds/trajectories do not establish independence.'))
 with(R/'SCENARIO_SUMMARY.csv').open('w',newline='',encoding='utf-8-sig')as f:w=csv.DictWriter(f,fieldnames=list(groups[0]));w.writeheader();w.writerows(groups)
 (R/'RNG_REPETITION_AUDIT.json').write_text(json.dumps(dict(source='O24 uniform=clock-seeded xxHash; Gaussian=minstd_rand0 default +2500cache. Not MT19937.',rows=rng,independence_claim=False),indent=2)+'\n')
 qualified=sum(x['QA']['qualification'].startswith('PASS')for x in records);technical=len(records)-qualified
 lines=['# 冻结O24论文停止门：第一批12槽原生闭环筛查','',f'当前登记 {len(records)}/12 个预定槽位，其中合格运行 {qualified}、技术中止 {technical}。A2×3、B2×5、C3×2、D4×1、E3×1；槽位计数不等于完成定位次数。','', '这些是固定保存世界上的原生程序重复，不是12个独立气体世界，不保证独立随机流，不给IID置信区间或显著性结论。', '', '|配置|已登记槽位|原生声明|声明时Top5误差m|平均声明物理时间s|源域资格|','|---|---:|---:|---|---:|---|']
 for x in groups:lines.append(f"|{x['case']}|{x['completed']}|{x['native_declared']}|{x['declared_Top5_errors_m']}|{x['mean_declared_search_physical_s']}|{x['source_domain']}|")
 lines+=['','## 指标和停止规则','', '官方success只表示原生方差声明，不表示定位正确。原生方差门1m²，关闭旧300秒普通停止。数据结束、磁盘安全门及技术watchdog均单列，不冒称原生成功/推断失败。源格不合法时真源rank为空；其最终估计误差可以报告，但不并入合格推断失败率。', '', 'B2真源三维释放合法，但被原始二维候选规则排除。按用户明确配额保留5次原生诊断，不移动真源、不打开源格。C3/D4/E3按合法源和完整资产的字典序选取，记录选择依据，非按本轮成绩挑选。', '', '同一冻结e63二进制；原始官方场景参数逐配置使用，C3的forward noise为官方配置0.25，其他所选配置按官方默认/覆盖值；局地GMRF权限保持一致。原始导航适配、地图、源、参数和时间线均有SHA。统一ROS物理时钟、1倍回放、连续既有帧不循环，属于单独协议，不覆盖旧O24-1.5/300墙钟。', '', '## A2先导结果与论文','', '已验收A2：Top5=0.242494m、MAP=0.257391m、真源rank2、方差0.688312m²，搜索467.092物理秒、约468.67墙钟秒。245个消费窗口，200个正检出；2662张候选评分复算最大相对误差约3.8e-15；物理查询时钟对应残差0。', '', '论文A2图示均值约0.6m、87.0s（30次，图中四舍五入标注）。本次单次误差较小，时间并不一致。模拟时间/加速、硬件、风信息和历史气体实现不能假定与作者完全相同；不能宣布优于论文或已严格复现统计性能。', '', '## 版本归因与历史证据','', 'O24是作者2024-09-18 a8源码的可核对移植。主要评分/命中图/规划保留，增加空窗口与地图就绪guard、被动记录，并修复矩形均值/方差宽高循环。后者确有数值影响，已在同输入C++审计归因；3964张历史候选图评分两版相同，不表示完整闭环逐位等价。准确作者实验commit未披露。旧H26 B4不计O24缺陷。', '', '## 保存与边界','', '每次有独立checkpoint、完整候选图/后验/RNG/原始CDR/服务/导航/成本。每次进下一运行前，先在C盘生成完整档案并逐成员解压SHA核验；仅空间紧张时才清理已验证档案的重复大导出工作副本。唯一气体世界、冻结源码/ELF/配置不删除。', '', '此批不实现受控seed适配，不做M2/M3、ROS新算法或新气体生成。受控RNG方案仅另存设计说明。','', '论文依据：[PMFS v3 VI-B及图10–11](https://arxiv.org/html/2304.08879v3)，[作者固定历史提交](https://github.com/MAPIRlab/GasSourceLocalization/commit/a8d5a764b7cbfc1d5d1887aebfe890e2c75d7533)。']
 lines+=['','## 给Pro的源候选域问题专项材料','', '见 domain_audit/FOR_PRO_SOURCE_DOMAIN_MISMATCH_zh.md。随包脚本已从作者原始地图/YAML、实际原生地图、三维占据网格和原生全候选快照，独立复算B2排除：三维源自由、二维源像素占据；本轮地图与作者地图0像素差异，最近合法中心距真源0.248294m。此事实不等于已经解释约两米误差，也不证明改源域即可获得独立创新。', '', 'B2_R04 已接受一次原生目标，后因同UID sftp-server 环境不可读触发保守隔离门，保留为技术中止，不作为定位失败或声明成功，也不补跑该槽。没有观察到外来ROS域进程，历史隔离仍无法认证。重新确认当前进程与DDS图为空、二进制未变后，按 RESUME_AMENDMENT_R3.json 继续其余原定槽位；隔离规则和科学参数未放宽。']
 (R/'中文筛查报告.md').write_text('\n'.join(lines)+'\n',encoding='utf8');return dict(accounted_slots=len(records),qualified_scientific_runs=qualified,technical_abort_slots=technical,groups=groups)
